mapper.select:
SELECT
    t.pay_id payId,
    t.order_id orderId,
    t.transaction_id transactionId,
    t.busi_id busiId,
    t.total_fee totalFee,
    t.remaining_fee remainingFee,
    t.pay_name payName,
    t.open_id openId,
    t.state state,
    t.message message,
    t.create_time createTime,
    t.status_cd statusCd,
    t.payment_pool_id paymentPoolId,
    t.app_id appId
FROM online_pay t
WHERE 1 = 1

    AND t.pay_id = #{payId}


    AND t.order_id = #{orderId}


    AND t.transaction_id = #{transactionId}


    AND t.busi_id = #{busiId}


    AND t.state = #{state}


    AND t.open_id = #{openId}


    AND t.payment_pool_id = #{paymentPoolId}


    AND t.app_id = #{appId}


    AND t.status_cd = #{statusCd}

ORDER BY t.create_time DESC

    limit #{page}, #{row}

SELECT count(1) count
FROM online_pay t
WHERE 1 = 1

    AND t.pay_id = #{payId}


    AND t.order_id = #{orderId}


    AND t.transaction_id = #{transactionId}


    AND t.busi_id = #{busiId}


    AND t.state = #{state}


    AND t.open_id = #{openId}


    AND t.payment_pool_id = #{paymentPoolId}


    AND t.app_id = #{appId}


    AND t.status_cd = #{statusCd}
